#!/usr/bin/env python3
"""ZOWN: follow / close friends + Everyone / Following / Close Friends filter on Leaderboard, Challenges and Duels.
Run from the expo/ folder:  python3 apply_audience_filter.py
All-or-nothing: every change is matched in memory first and nothing is written unless all of it matches."""
import os, sys

NEW_FILES = {
 "lib/audience.js": "// lib/audience.js\n//\n// Pure helpers for the Everyone / Following / Close Friends filter used by\n// the Leaderboard, Challenges and Duels screens. \"Following\" is everyone you\n// follow (close friends included). \"Close Friends\" is the private subset you\n// starred. Nothing here talks to Firebase.\n\nexport const AUDIENCES = [\n  { id: 'everyone', label: 'Everyone' },\n  { id: 'following', label: 'Following' },\n  { id: 'close', label: 'Close Friends' },\n];\n\nexport const DEFAULT_AUDIENCE = 'everyone';\n\nexport function isAudience(value) {\n  return AUDIENCES.some((a) => a.id === value);\n}\n\n/** follows: [{ uid, close? }]. Returns the uids an audience covers, or null for everyone. */\nexport function audienceUids(audience, follows) {\n  if (audience !== 'following' && audience !== 'close') return null;\n  const list = Array.isArray(follows) ? follows : [];\n  return list\n    .filter((f) => f && typeof f.uid === 'string' && f.uid && (audience === 'following' || f.close === true))\n    .map((f) => f.uid);\n}\n\n/**\n * Keeps the items whose uid is in the audience. `everyone` keeps all.\n * The signed-in user's own item is kept when keepSelf is true, so a\n * leaderboard filtered to friends still shows where you stand.\n */\nexport function filterByAudience(items, audience, follows, { getUid = (x) => x.uid, myUid = null, keepSelf = false } = {}) {\n  const uids = audienceUids(audience, follows);\n  const list = Array.isArray(items) ? items : [];\n  if (uids === null) return list;\n  const set = new Set(uids);\n  return list.filter((item) => {\n    const uid = getUid(item);\n    if (keepSelf && myUid && uid === myUid) return true;\n    return set.has(uid);\n  });\n}\n\n/** Splits a list into groups of at most `size` (Firestore `in` queries allow 10). */\nexport function chunk(list, size = 10) {\n  const out = [];\n  const arr = Array.isArray(list) ? list : [];\n  for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size));\n  return out;\n}\n\n/** Highest first by `field`, ties broken by name then id so the order never jumps around. */\nexport function rankEntries(entries, field = 'xp') {\n  return [...(Array.isArray(entries) ? entries : [])]\n    .sort((a, b) => {\n      const diff = (Number(b?.[field]) || 0) - (Number(a?.[field]) || 0);\n      if (diff !== 0) return diff;\n      const byName = String(a?.name || '').localeCompare(String(b?.name || ''));\n      return byName !== 0 ? byName : String(a?.id || '').localeCompare(String(b?.id || ''));\n    })\n    .map((entry, i) => ({ ...entry, rank: i + 1 }));\n}\n\n/** Document id for one person's progress in one challenge. */\nexport function challengeEntryId(challengeId, uid) {\n  return `${challengeId}_${uid}`;\n}\n\n/** Text shown when a filtered list is empty. */\nexport function emptyAudienceMessage(surface, audience) {\n  const noun = { leaderboard: 'on the leaderboard', challenges: 'in this challenge', duels: 'with duels' }[surface] || 'here';\n  if (audience === 'close') return `None of your close friends are ${noun} yet. Star people from the Friends screen to add them.`;\n  if (audience === 'following') return `Nobody you follow is ${noun} yet. Tap a person to follow them.`;\n  return surface === 'leaderboard' ? 'No one on the leaderboard yet.' : 'Nothing to show yet.';\n}\n\n/** What changed for one person when you set a follow / close friend state. */\nexport function nextFollowState(current, action) {\n  const cur = current && typeof current === 'object' ? current : null;\n  if (action === 'follow') return { following: true, close: cur ? cur.close === true : false };\n  if (action === 'unfollow') return { following: false, close: false }; // unfollowing also removes them from close friends\n  if (action === 'addClose') return { following: true, close: true };   // close friends are always people you follow\n  if (action === 'removeClose') return { following: !!cur, close: false };\n  return { following: !!cur, close: cur ? cur.close === true : false };\n}\n",
 "store/socialGraphStore.js": "// store/socialGraphStore.js\n//\n// Who you follow, and which of them are Close Friends. Both lists are\n// private to you: users/{uid}/following/{otherUid} (see firestore.rules).\n// Following is one-way, like Instagram: you do not need their approval and\n// they are not told. Close Friends is a private star you put on someone you\n// follow; it only changes what YOU see when you pick the Close Friends\n// filter. Also remembers the Everyone / Following / Close Friends choice for\n// each screen that has the filter.\nimport { create } from 'zustand';\nimport { persist, createJSONStorage } from 'zustand/middleware';\nimport AsyncStorage from '@react-native-async-storage/async-storage';\nimport { db } from '../src/config/firebase';\nimport { collection, doc, getDocs, setDoc, deleteDoc } from 'firebase/firestore';\nimport { DEFAULT_AUDIENCE, isAudience, nextFollowState } from '../lib/audience';\n\nexport const useSocialGraphStore = create(\n  persist(\n    (set, get) => ({\n      following: [], // [{ uid, name, avatar, close, followedAt }]\n      isLoaded: false,\n      isLoading: false,\n      audience: { leaderboard: DEFAULT_AUDIENCE, challenges: DEFAULT_AUDIENCE, duels: DEFAULT_AUDIENCE },\n\n      setAudience: (surface, value) => {\n        if (!isAudience(value)) return;\n        set((s) => ({ audience: { ...s.audience, [surface]: value } }));\n      },\n\n      loadFollowing: async (uid) => {\n        if (!uid) return;\n        set({ isLoading: true });\n        try {\n          const snap = await getDocs(collection(db, 'users', uid, 'following'));\n          const following = snap.docs.map((d) => {\n            const data = d.data() || {};\n            return {\n              uid: d.id,\n              name: data.name || 'Zown User',\n              avatar: data.avatar || null,\n              close: data.close === true,\n              followedAt: data.followedAt || null,\n            };\n          });\n          set({ following, isLoaded: true });\n        } catch (e) {\n          console.warn('[socialGraphStore] loadFollowing error:', e?.message);\n        } finally {\n          set({ isLoading: false });\n        }\n      },\n\n      isFollowing: (uid) => get().following.some((f) => f.uid === uid),\n      isClose: (uid) => get().following.some((f) => f.uid === uid && f.close),\n      getRecord: (uid) => get().following.find((f) => f.uid === uid) || null,\n\n      // action: 'follow' | 'unfollow' | 'addClose' | 'removeClose'\n      // person: { uid, name, avatar }\n      updateRelationship: async (myUid, person, action) => {\n        if (!myUid || !person?.uid || person.uid === myUid) return false;\n        const before = get().following;\n        const existing = before.find((f) => f.uid === person.uid) || null;\n        const next = nextFollowState(existing, action);\n        const record = {\n          uid: person.uid,\n          name: person.name || existing?.name || 'Zown User',\n          avatar: person.avatar || existing?.avatar || null,\n          close: next.close,\n          followedAt: existing?.followedAt || new Date().toISOString(),\n        };\n        // Optimistic: update the list now, put it back if the save fails.\n        set({\n          following: next.following\n            ? [...before.filter((f) => f.uid !== person.uid), record]\n            : before.filter((f) => f.uid !== person.uid),\n        });\n        try {\n          const ref = doc(db, 'users', myUid, 'following', person.uid);\n          if (next.following) {\n            await setDoc(ref, {\n              name: record.name,\n              avatar: record.avatar,\n              close: record.close,\n              followedAt: record.followedAt,\n            });\n          } else {\n            await deleteDoc(ref);\n          }\n          return true;\n        } catch (e) {\n          console.warn('[socialGraphStore] updateRelationship error:', e?.message);\n          set({ following: before });\n          return false;\n        }\n      },\n\n      clear: () => set({ following: [], isLoaded: false }),\n    }),\n    {\n      name: 'zown-social-graph',\n      storage: createJSONStorage(() => AsyncStorage),\n      // Only the filter choices are remembered on the phone. The follow list\n      // always comes fresh from Firestore.\n      partialize: (state) => ({ audience: state.audience }),\n    }\n  )\n);\n",
 "store/useAudience.js": "// store/useAudience.js\n//\n// One hook for the Everyone / Following / Close Friends filter on a screen:\n// loads who you follow, remembers the pick for that screen, and gives back\n// the list of uids the pick covers (null means everyone).\nimport { useEffect, useMemo } from 'react';\nimport { useSocialGraphStore } from './socialGraphStore';\nimport { audienceUids } from '../lib/audience';\n\nexport function useAudience(surface, myUid) {\n  const audience = useSocialGraphStore((s) => s.audience[surface]) || 'everyone';\n  const setAudienceFor = useSocialGraphStore((s) => s.setAudience);\n  const following = useSocialGraphStore((s) => s.following);\n  const loadFollowing = useSocialGraphStore((s) => s.loadFollowing);\n\n  useEffect(() => {\n    if (myUid) loadFollowing(myUid);\n  }, [myUid]);\n\n  const uids = useMemo(() => audienceUids(audience, following), [audience, following]);\n  const uidKey = uids === null ? 'all' : uids.join(',');\n\n  return {\n    audience,\n    setAudience: (value) => setAudienceFor(surface, value),\n    follows: following,\n    uids,\n    uidKey,\n  };\n}\n",
 "components/AudienceFilter.jsx": "// components/AudienceFilter.jsx\n//\n// Everyone / Following / Close Friends pills, shared by the Leaderboard,\n// Challenges and Duels screens (store/socialGraphStore.js remembers the pick\n// per screen).\nimport React from 'react';\nimport { View, Text, Pressable, StyleSheet } from 'react-native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { AUDIENCES } from '../lib/audience';\n\nexport default function AudienceFilter({ value, onChange, style }) {\n  return (\n    <View style={[styles.row, style]} accessibilityRole=\"tablist\">\n      {AUDIENCES.map((a) => {\n        const active = value === a.id;\n        return (\n          <Pressable\n            key={a.id}\n            onPress={() => onChange(a.id)}\n            style={[styles.pill, active && styles.pillActive]}\n            accessibilityRole=\"tab\"\n            accessibilityState={{ selected: active }}\n          >\n            {a.id === 'close' && (\n              <Ionicons name=\"star\" size={12} color={active ? '#FFFFFF' : '#16A34A'} style={{ marginRight: 4 }} />\n            )}\n            <Text style={[styles.text, active && styles.textActive]}>{a.label}</Text>\n          </Pressable>\n        );\n      })}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  row: { flexDirection: 'row', flexWrap: 'wrap', gap: 8 },\n  pill: {\n    flexDirection: 'row', alignItems: 'center',\n    backgroundColor: '#F0F0F0', paddingHorizontal: 14, paddingVertical: 8, borderRadius: 999,\n  },\n  pillActive: { backgroundColor: '#000000' },\n  text: { fontSize: 13, fontWeight: '600', color: '#555555' },\n  textActive: { color: '#FFFFFF' },\n});\n",
 "components/PersonSheet.jsx": "// components/PersonSheet.jsx\n//\n// Bottom sheet with what you can do with another person: follow / unfollow,\n// add to / remove from Close Friends, and (when the screen supports it)\n// challenge them to a duel. Close Friends are always people you follow, so\n// starring someone also follows them.\nimport React from 'react';\nimport { View, Text, Pressable, Modal, StyleSheet } from 'react-native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { useSocialGraphStore } from '../store/socialGraphStore';\nimport { useUserStore } from '../store/userStore';\n\nexport default function PersonSheet({ person, onClose, onDuel }) {\n  const { user } = useUserStore();\n  const following = useSocialGraphStore((s) => s.following);\n  const updateRelationship = useSocialGraphStore((s) => s.updateRelationship);\n\n  const record = person ? following.find((f) => f.uid === person.uid) : null;\n  const isFollowing = !!record;\n  const isClose = !!record?.close;\n\n  const run = async (action) => {\n    if (!person || !user?.uid) return;\n    await updateRelationship(user.uid, person, action);\n  };\n\n  return (\n    <Modal visible={!!person} transparent animationType=\"slide\" onRequestClose={onClose}>\n      <Pressable style={styles.backdrop} onPress={onClose} />\n      <View style={styles.sheet}>\n        <View style={styles.header}>\n          <View style={styles.avatar}>\n            <Text style={styles.avatarText}>{(person?.name || '?').slice(0, 1).toUpperCase()}</Text>\n          </View>\n          <View style={{ flex: 1 }}>\n            <Text style={styles.name} numberOfLines={1}>{person?.name}</Text>\n            <Text style={styles.sub}>\n              {isClose ? 'Close friend' : isFollowing ? 'You follow them' : 'Not following'}\n            </Text>\n          </View>\n          <Pressable onPress={onClose} hitSlop={10}><Ionicons name=\"close\" size={22} color=\"#000\" /></Pressable>\n        </View>\n\n        <Pressable style={styles.row} onPress={() => run(isFollowing ? 'unfollow' : 'follow')}>\n          <Ionicons name={isFollowing ? 'person-remove-outline' : 'person-add-outline'} size={20} color=\"#000\" />\n          <Text style={styles.rowText}>{isFollowing ? 'Unfollow' : 'Follow'}</Text>\n        </Pressable>\n\n        <Pressable style={styles.row} onPress={() => run(isClose ? 'removeClose' : 'addClose')}>\n          <Ionicons name={isClose ? 'star' : 'star-outline'} size={20} color=\"#16A34A\" />\n          <View style={{ flex: 1 }}>\n            <Text style={styles.rowText}>{isClose ? 'Remove from Close Friends' : 'Add to Close Friends'}</Text>\n            <Text style={styles.rowHint}>Only you can see your Close Friends list.</Text>\n          </View>\n        </Pressable>\n\n        {!!onDuel && (\n          <Pressable style={styles.row} onPress={() => { const target = person; onClose(); setTimeout(() => onDuel(target), 400); }}>\n            <Ionicons name=\"flash-outline\" size={20} color=\"#000\" />\n            <Text style={styles.rowText}>Challenge to a duel</Text>\n          </Pressable>\n        )}\n      </View>\n    </Modal>\n  );\n}\n\nconst styles = StyleSheet.create({\n  backdrop: { flex: 1, backgroundColor: 'rgba(0,0,0,0.35)' },\n  sheet: { backgroundColor: '#FFFFFF', borderTopLeftRadius: 20, borderTopRightRadius: 20, padding: 20, paddingBottom: 36 },\n  header: { flexDirection: 'row', alignItems: 'center', gap: 12, marginBottom: 12 },\n  avatar: { width: 44, height: 44, borderRadius: 22, backgroundColor: '#000', alignItems: 'center', justifyContent: 'center' },\n  avatarText: { color: '#FFF', fontWeight: '700', fontSize: 16 },\n  name: { fontSize: 17, fontWeight: '700', color: '#000' },\n  sub: { fontSize: 12, color: '#888', marginTop: 2 },\n  row: { flexDirection: 'row', alignItems: 'center', gap: 14, paddingVertical: 14, borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: '#E5E5E5' },\n  rowText: { fontSize: 15, fontWeight: '600', color: '#000' },\n  rowHint: { fontSize: 12, color: '#999', marginTop: 2 },\n});\n",
 "app/friends.jsx": "// app/friends.jsx\n//\n// Manage who you follow and who your Close Friends are. Close Friends is a\n// private list - only you see it - used by the Close Friends filter on the\n// Leaderboard, Challenges and Duels. Find people by name among the ranked\n// users on the leaderboard (the only public list of people in the app).\nimport React, { useEffect, useMemo, useState } from 'react';\nimport { View, Text, StyleSheet, ScrollView, TextInput, Pressable, ActivityIndicator } from 'react-native';\nimport { Ionicons } from '@expo/vector-icons';\nimport ScreenHeader from '@/components/ScreenHeader';\nimport PersonSheet from '@/components/PersonSheet';\nimport { useUserStore } from '@/store/userStore';\nimport { useSocialGraphStore } from '@/store/socialGraphStore';\nimport { useLeaderboardStore } from '@/store/leaderboardStore';\n\nfunction Row({ person, onPress, onStar, starred, subtitle }) {\n  return (\n    <Pressable style={styles.row} onPress={onPress}>\n      <View style={styles.avatar}><Text style={styles.avatarText}>{(person.name || '?').slice(0, 1).toUpperCase()}</Text></View>\n      <View style={{ flex: 1 }}>\n        <Text style={styles.name} numberOfLines={1}>{person.name}</Text>\n        {!!subtitle && <Text style={styles.sub}>{subtitle}</Text>}\n      </View>\n      {!!onStar && (\n        <Pressable onPress={onStar} hitSlop={10} accessibilityLabel={starred ? 'Remove from Close Friends' : 'Add to Close Friends'}>\n          <Ionicons name={starred ? 'star' : 'star-outline'} size={22} color=\"#16A34A\" />\n        </Pressable>\n      )}\n    </Pressable>\n  );\n}\n\nexport default function FriendsScreen() {\n  const { user } = useUserStore();\n  const following = useSocialGraphStore((s) => s.following);\n  const isLoading = useSocialGraphStore((s) => s.isLoading);\n  const loadFollowing = useSocialGraphStore((s) => s.loadFollowing);\n  const updateRelationship = useSocialGraphStore((s) => s.updateRelationship);\n  const { entries, loadTop } = useLeaderboardStore();\n  const [search, setSearch] = useState('');\n  const [sheetPerson, setSheetPerson] = useState(null);\n\n  useEffect(() => {\n    if (user?.uid) loadFollowing(user.uid);\n    loadTop(100);\n  }, [user?.uid]);\n\n  const close = useMemo(() => following.filter((f) => f.close).sort((a, b) => a.name.localeCompare(b.name)), [following]);\n  const others = useMemo(() => following.filter((f) => !f.close).sort((a, b) => a.name.localeCompare(b.name)), [following]);\n\n  const query = search.trim().toLowerCase();\n  const results = query\n    ? entries\n        .filter((e) => e.id !== user?.uid && (e.name || '').toLowerCase().includes(query))\n        .slice(0, 10)\n    : [];\n\n  const toggleStar = (f) => updateRelationship(user?.uid, f, f.close ? 'removeClose' : 'addClose');\n\n  return (\n    <View style={styles.container}>\n      <ScreenHeader title=\"Friends\" showBack />\n      <ScrollView contentContainerStyle={{ padding: 20, paddingBottom: 60 }} keyboardShouldPersistTaps=\"handled\">\n        <View style={styles.searchBar}>\n          <Ionicons name=\"search-outline\" size={18} color=\"#999\" />\n          <TextInput\n            value={search}\n            onChangeText={setSearch}\n            placeholder=\"Find people by name\"\n            placeholderTextColor=\"#999\"\n            style={styles.searchInput}\n            autoCorrect={false}\n          />\n          {!!search && (\n            <Pressable onPress={() => setSearch('')}><Ionicons name=\"close-circle\" size={18} color=\"#CCC\" /></Pressable>\n          )}\n        </View>\n\n        {!!query && (\n          <View style={{ marginBottom: 16 }}>\n            {results.length === 0 ? (\n              <Text style={styles.empty}>No one with that name on the leaderboard yet.</Text>\n            ) : (\n              results.map((e) => (\n                <Row\n                  key={e.id}\n                  person={{ name: e.name }}\n                  subtitle={following.some((f) => f.uid === e.id) ? 'Following' : null}\n                  onPress={() => setSheetPerson({ uid: e.id, name: e.name, avatar: e.avatar })}\n                />\n              ))\n            )}\n          </View>\n        )}\n\n        <Text style={styles.section}>Close Friends ({close.length})</Text>\n        {close.length === 0 ? (\n          <Text style={styles.empty}>Tap the star next to someone you follow to add them. Only you can see this list.</Text>\n        ) : (\n          close.map((f) => (\n            <Row key={f.uid} person={f} starred onStar={() => toggleStar(f)}\n              onPress={() => setSheetPerson({ uid: f.uid, name: f.name, avatar: f.avatar })} />\n          ))\n        )}\n\n        <Text style={styles.section}>Following ({others.length})</Text>\n        {isLoading && following.length === 0 ? (\n          <ActivityIndicator color=\"#000\" style={{ marginTop: 12 }} />\n        ) : others.length === 0 ? (\n          <Text style={styles.empty}>\n            {following.length === 0\n              ? 'You are not following anyone yet. Search above, or tap a person on the Leaderboard.'\n              : 'Everyone you follow is a close friend.'}\n          </Text>\n        ) : (\n          others.map((f) => (\n            <Row key={f.uid} person={f} starred={false} onStar={() => toggleStar(f)}\n              onPress={() => setSheetPerson({ uid: f.uid, name: f.name, avatar: f.avatar })} />\n          ))\n        )}\n      </ScrollView>\n      <PersonSheet person={sheetPerson} onClose={() => setSheetPerson(null)} />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  container: { flex: 1, backgroundColor: '#FFFFFF' },\n  searchBar: { flexDirection: 'row', alignItems: 'center', gap: 8, backgroundColor: '#F0F0F0', borderRadius: 12, paddingHorizontal: 12, height: 42, marginBottom: 16 },\n  searchInput: { flex: 1, fontSize: 14, color: '#000' },\n  section: { fontSize: 12, fontWeight: '700', color: '#999', textTransform: 'uppercase', letterSpacing: 0.5, marginTop: 16, marginBottom: 8 },\n  empty: { fontSize: 13, color: '#999', paddingVertical: 8 },\n  row: { flexDirection: 'row', alignItems: 'center', gap: 12, paddingVertical: 10 },\n  avatar: { width: 40, height: 40, borderRadius: 20, backgroundColor: '#000', alignItems: 'center', justifyContent: 'center' },\n  avatarText: { color: '#FFF', fontWeight: '700', fontSize: 15 },\n  name: { fontSize: 15, fontWeight: '600', color: '#000' },\n  sub: { fontSize: 12, color: '#888', marginTop: 2 },\n});\n",
 "__tests__/audience.test.js": "import {\n  AUDIENCES, audienceUids, filterByAudience, chunk, rankEntries, challengeEntryId,\n  emptyAudienceMessage, nextFollowState, isAudience,\n} from '../lib/audience';\n\nconst follows = [\n  { uid: 'a', name: 'Alex', close: true },\n  { uid: 'b', name: 'Bea', close: false },\n  { uid: 'c', name: 'Cam', close: true },\n  { uid: 'd', name: 'Dee' },\n  { uid: '', name: 'Broken' },\n  null,\n];\n\ndescribe('audiences', () => {\n  it('has the three choices in order', () => {\n    expect(AUDIENCES.map((a) => a.id)).toEqual(['everyone', 'following', 'close']);\n    expect(isAudience('close')).toBe(true);\n    expect(isAudience('friends')).toBe(false);\n  });\n\n  it('everyone means no filter', () => {\n    expect(audienceUids('everyone', follows)).toBeNull();\n    expect(audienceUids('anything-else', follows)).toBeNull();\n  });\n\n  it('following includes close friends; close is the starred subset; junk is ignored', () => {\n    expect(audienceUids('following', follows)).toEqual(['a', 'b', 'c', 'd']);\n    expect(audienceUids('close', follows)).toEqual(['a', 'c']);\n    expect(audienceUids('close', null)).toEqual([]);\n  });\n});\n\ndescribe('filterByAudience', () => {\n  const entries = [{ id: 'me' }, { id: 'a' }, { id: 'b' }, { id: 'x' }, { id: 'c' }];\n  const opts = { getUid: (e) => e.id, myUid: 'me' };\n\n  it('keeps everything for everyone', () => {\n    expect(filterByAudience(entries, 'everyone', follows, opts)).toHaveLength(5);\n  });\n  it('filters to following, or to close friends', () => {\n    expect(filterByAudience(entries, 'following', follows, opts).map((e) => e.id)).toEqual(['a', 'b', 'c']);\n    expect(filterByAudience(entries, 'close', follows, opts).map((e) => e.id)).toEqual(['a', 'c']);\n  });\n  it('can keep you in the list', () => {\n    expect(filterByAudience(entries, 'close', follows, { ...opts, keepSelf: true }).map((e) => e.id)).toEqual(['me', 'a', 'c']);\n  });\n  it('shows nobody when you follow nobody', () => {\n    expect(filterByAudience(entries, 'following', [], opts)).toEqual([]);\n  });\n});\n\ndescribe('helpers', () => {\n  it('chunks into groups of ten for Firestore in-queries', () => {\n    const ids = Array.from({ length: 23 }, (_, i) => `u${i}`);\n    expect(chunk(ids, 10).map((g) => g.length)).toEqual([10, 10, 3]);\n    expect(chunk([], 10)).toEqual([]);\n  });\n  it('ranks highest first with stable ties and adds rank', () => {\n    const ranked = rankEntries([\n      { id: '2', name: 'Bea', xp: 50 }, { id: '1', name: 'Alex', xp: 50 }, { id: '3', name: 'Cam', xp: 90 }, { id: '4', name: 'Dee' },\n    ]);\n    expect(ranked.map((e) => e.id)).toEqual(['3', '1', '2', '4']);\n    expect(ranked.map((e) => e.rank)).toEqual([1, 2, 3, 4]);\n    expect(rankEntries([{ id: 'a', current: 3 }, { id: 'b', current: 7 }], 'current')[0].id).toBe('b');\n  });\n  it('builds the challenge entry id the Firestore rule checks', () => {\n    expect(challengeEntryId('week-2026-10-05', 'uid1')).toBe('week-2026-10-05_uid1');\n  });\n  it('words empty states for each audience', () => {\n    expect(emptyAudienceMessage('leaderboard', 'close')).toContain('close friends');\n    expect(emptyAudienceMessage('challenges', 'following')).toContain('follow');\n    expect(emptyAudienceMessage('leaderboard', 'everyone')).toContain('No one');\n  });\n});\n\ndescribe('follow state', () => {\n  it('following keeps an existing close-friend star', () => {\n    expect(nextFollowState(null, 'follow')).toEqual({ following: true, close: false });\n    expect(nextFollowState({ close: true }, 'follow')).toEqual({ following: true, close: true });\n  });\n  it('unfollowing also removes the close-friend star', () => {\n    expect(nextFollowState({ close: true }, 'unfollow')).toEqual({ following: false, close: false });\n  });\n  it('starring someone follows them; unstarring keeps the follow', () => {\n    expect(nextFollowState(null, 'addClose')).toEqual({ following: true, close: true });\n    expect(nextFollowState({ close: true }, 'removeClose')).toEqual({ following: true, close: false });\n    expect(nextFollowState(null, 'removeClose')).toEqual({ following: false, close: false });\n  });\n});\n"
}

